@forelse($runs as $run)
<article class="run-row"><div class="run-title"><strong>{{ $names[$run->avatar_id]??$run->avatar_id }} &middot; {{ $run->created_at->timezone('Asia/Manila')->format('M j, g:i A') }}</strong><span class="badge">{{ str_replace('_',' ',$run->status) }}</span></div>
@php($progress=$run->state['node_progress']??$run->state['sampler_progress']??[])
<p>{{ $run->state['stage']??'Waiting in GPU queue' }} @if(isset($progress['value']))&middot; Node progress {{ $progress['value'] }}/{{ $progress['max']??'?' }}@endif</p>
@if(isset($run->state['reason']))<p class="fine">{{ $run->state['reason'] }}</p>@endif
